function nx_cm(stdClass $course,string $mod,string $id):?stdClass { global $DB; $sql='SELECT cm.* FROM {course_modules} cm JOIN {modules} m ON m.id=cm.module WHERE cm.course=? AND cm.idnumber=? AND cm.deletioninprogress=0 AND m.name=?'; return $DB->get_record_sql($sql,[$course->id,$id,$mod])?:null; }
function nx_panel(string $h,string $b):string { return '<section style="border-left:4px solid #245b73;background:#f4fafb;padding:1rem 1.1rem;margin:1rem 0;border-radius:.35rem"><h3 style="margin-top:0">'.s($h).'</h3>'.$b.'</section>'; }
function nx_render_chapter(array $c,bool $video):string { $ul=static fn(array $a):string=>'<ul>'.implode('',array_map(static fn(string $v):string=>'<li>'.s($v).'</li>',$a)).'</ul>'; $h='<div class="nexus-course-lesson"><p><strong>Curriculum connection:</strong> '.s(implode(', ',$c['expectations'])).'</p>'.nx_panel('Learning goals',$ul(['Explain the key ideas using accurate terminology.','Apply the ideas to an unfamiliar example or problem.','Document evidence, decisions, and a justified next step.'])).nx_panel('Success criteria',$ul(['I can define and use the vocabulary accurately.','I can connect a choice to evidence, criteria, or audience.','I can identify a limitation and propose a revision.'])).'<h3>Key vocabulary</h3><p>'.s($c['vocabulary']).'</p><h3>Detailed lesson</h3><p>'.s($c['explanation']).'</p><h3>Worked visual or technical example</h3><p>'.s('Create a labelled example from the lesson: identify the user or audience, show the relevant elements or parts, annotate the decision, and state how you would test it. Compare your example with a peer or teacher model without copying it.').'</p>';
  if($video){ foreach($c['videos'] as $i=>$v){$f=basename($v);$h.='<h3>Learning video '.($i+1).'</h3><video controls preload="metadata" playsinline style="display:block;width:100%;max-width:100%;height:auto;aspect-ratio:16/9;background:#000;border-radius:.5rem" aria-label="'.s($c['title'].' learning video '.($i+1)).'"><source src="@@PLUGINFILE@@/'.rawurlencode($f).'" type="video/mp4">Your browser does not support this video. Use the written lesson and contact your teacher for an accessible alternative.</video><p><strong>Viewing purpose:</strong> pause to record one key idea, one example, and one question.</p>'; } }
  if(!empty($c['decks'])){$h.='<h3>Teacher source presentation</h3><ul>';foreach($c['decks'] as $d){$fn=basename($d);$h.='<li><a href="@@PLUGINFILE@@/'.rawurlencode($fn).'">'.s($fn).' (PPTX download)</a></li>';}$h.='</ul><p>Use the presentation as a companion visual reference; complete the written task in your own words.</p>';}
  $h.='<h3>Check your understanding</h3>'.$ul($c['checks']).'<h3>Hands-on task</h3><p>'.s($c['task']).'</p>'.nx_panel('Reflection and next step','<p>Write what changed in your understanding, cite one piece of evidence, and name the next action you will take. Keep this entry in your design journal or sketchbook.</p>').'<h3>Key takeaways</h3><ul><li>Design and art decisions should be intentional and explainable.</li><li>Evidence and feedback make revision stronger.</li><li>Clear documentation is part of the work.</li></ul></div>'; return $h; }
function nx_page(stdClass $course,int $section,string $id,string $name,string $html):array { global $DB; if($cm=nx_cm($course,'page',$id))return[$cm,false]; $i=(object)['modulename'=>'page','module'=>$DB->get_field('modules','id',['name'=>'page'],MUST_EXIST),'name'=>$name,'intro'=>'','introformat'=>FORMAT_HTML,'content'=>$html,'contentformat'=>FORMAT_HTML,'section'=>$section,'visible'=>1,'cmidnumber'=>$id,'completion'=>COMPLETION_TRACKING_AUTOMATIC,'completionview'=>1];$x=add_moduleinfo($i,$course);return[$DB->get_record('course_modules',['id'=>$x->coursemodule], '*',MUST_EXIST),true]; }
