function nx_book(stdClass $course,int $section,string $id,string $name,string $intro):array { global $DB; if($cm=nx_cm($course,'book',$id))return[$cm,$DB->get_record('book',['id'=>$cm->instance], '*',MUST_EXIST),false];$i=(object)['modulename'=>'book','module'=>$DB->get_field('modules','id',['name'=>'book'],MUST_EXIST),'name'=>$name,'intro'=>$intro,'introformat'=>FORMAT_HTML,'numbering'=>1,'navstyle'=>1,'customtitles'=>0,'section'=>$section,'visible'=>1,'cmidnumber'=>$id,'completion'=>COMPLETION_TRACKING_AUTOMATIC,'completionview'=>1];$x=add_moduleinfo($i,$course);$cm=$DB->get_record('course_modules',['id'=>$x->coursemodule], '*',MUST_EXIST);return[$cm,$DB->get_record('book',['id'=>$x->instance], '*',MUST_EXIST),true]; }
function nx_chapter(stdClass $book,stdClass $cm,array $c,string $media,array &$sum,bool $videos):void { global $DB; $r=$DB->get_record('book_chapters',['bookid'=>$book->id,'importsrc'=>$c['id']]);$content=nx_render_chapter($c,$videos); if(!$r){$r=(object)['bookid'=>$book->id,'pagenum'=>(int)$DB->get_field_sql('SELECT COALESCE(MAX(pagenum),0)+1 FROM {book_chapters} WHERE bookid=?',[$book->id]),'subchapter'=>0,'title'=>$c['title'],'content'=>$content,'contentformat'=>FORMAT_HTML,'hidden'=>0,'timecreated'=>time(),'timemodified'=>time(),'importsrc'=>$c['id']];$r->id=$DB->insert_record('book_chapters',$r);$sum['chapters_created']++;}else{$r->title=$c['title'];$r->content=$content;$r->timemodified=time();$DB->update_record('book_chapters',$r);$sum['chapters_updated']++;} $fs=get_file_storage();$ctx=context_module::instance((int)$cm->id); foreach(array_merge($c['videos']??[],$c['decks']??[]) as $rel){$src=$media.'/'.$rel;if(!is_readable($src))throw new RuntimeException('Missing staged file '.$rel);$fn=basename($rel);$old=$fs->get_file($ctx->id,'mod_book','chapter',(int)$r->id,'/',$fn);$hash=sha1_file($src);if($old && $old->get_contenthash()===$hash){$sum['files_existing']++;continue;}if($old)$old->delete();$fs->create_file_from_pathname(['contextid'=>$ctx->id,'component'=>'mod_book','filearea'=>'chapter','itemid'=>(int)$r->id,'filepath'=>'/','filename'=>$fn],$src);$sum['files_imported']++; if(str_ends_with(strtolower($fn),'.mp4'))$sum['videos_imported']++; else $sum['decks_imported']++;} }
