function nx_question(context_course $ctx,string $catid,string $qid,string $text):stdClass { global $DB; $cat=$DB->get_record('question_categories',['contextid'=>$ctx->id,'idnumber'=>$catid]); if(!$cat){$top=question_get_top_category($ctx->id,true);$cat=(object)['name'=>$catid,'info'=>'Nexus formative course question bank.','infoformat'=>FORMAT_HTML,'stamp'=>make_unique_id_code(),'idnumber'=>$catid,'parent'=>$top->id,'contextid'=>$ctx->id,'sortorder'=>1];$cat->id=$DB->insert_record('question_categories',$cat);} $sql='SELECT q.* FROM {question} q JOIN {question_versions} qv ON qv.questionid=q.id JOIN {question_bank_entries} qbe ON qbe.id=qv.questionbankentryid WHERE qbe.questioncategoryid=? AND qbe.idnumber=? ORDER BY qv.version DESC';if($q=$DB->get_record_sql($sql,[$cat->id,$qid]))return$q;$question=(object)['qtype'=>'multichoice','createdby'=>0,'idnumber'=>$qid,'status'=>\core_question\local\bank\question_version_status::QUESTION_STATUS_READY];$form=(object)['name'=>$qid,'questiontext'=>['text'=>'<p>'.s($text).'</p>','format'=>FORMAT_HTML],'generalfeedback'=>['text'=>'<p>Review the lesson and explain your reasoning.</p>','format'=>FORMAT_HTML],'defaultmark'=>1,'penalty'=>0.1,'status'=>\core_question\local\bank\question_version_status::QUESTION_STATUS_READY,'category'=>$cat->id.','.$ctx->id,'idnumber'=>$qid,'shuffleanswers'=>1,'answernumbering'=>'abc','single'=>'1','correctfeedback'=>['text'=>'Correct.','format'=>FORMAT_HTML],'partiallycorrectfeedback'=>['text'=>'Partly correct.','format'=>FORMAT_HTML],'incorrectfeedback'=>['text'=>'Revisit the evidence and try again.','format'=>FORMAT_HTML],'correctfeedbackformat'=>FORMAT_HTML,'partiallycorrectfeedbackformat'=>FORMAT_HTML,'incorrectfeedbackformat'=>FORMAT_HTML,'fraction'=>['1.0','0.0','0.0'],'answer'=>[['text'=>'It is the best-supported design or artistic decision.','format'=>FORMAT_PLAIN],['text'=>'It is chosen without evidence.','format'=>FORMAT_PLAIN],['text'=>'It ignores the audience and constraints.','format'=>FORMAT_PLAIN]],'feedback'=>[['text'=>'This connects choices to evidence.','format'=>FORMAT_HTML],['text'=>'Use criteria and evidence.','format'=>FORMAT_HTML],['text'=>'Consider audience and constraints.','format'=>FORMAT_HTML]]];return question_bank::get_qtype('multichoice')->save_question($question,$form); }
function nx_attach(stdClass $quiz,stdClass $q):void { global $DB; if(!$DB->record_exists_sql('SELECT 1 FROM {quiz_slots} qs JOIN {question_references} qr ON qr.itemid=qs.id JOIN {question_versions} qv ON qv.questionbankentryid=qr.questionbankentryid WHERE qs.quizid=? AND qv.questionid=?',[$quiz->id,$q->id]))quiz_add_quiz_question($q->id,$quiz,0,1.0); }
